   656  /*!
   657   * \brief   pixExtractBarcodeWidths2()
   658   *
   659   * \param[in]    pixs        input image; 8 bpp
   660   * \param[in]    thresh      estimated pixel threshold for crossing
   661   *                           white <--> black; typ. ~120
   662   * \param[out]   pwidth      [optional] best decoding window width, in pixels
   663   * \param[out]   pnac        [optional] number of transitions in each window
   664   * \param[in]    debugflag   use 1 to generate debug output
   665   * \return  nad   numa of barcode widths in encoded integer units,
   666   *                or NULL on error
   667   *
   668   * <pre>
   669   * Notes:
   670   *      (1) The widths are alternating black/white, starting with black
   671   *          and ending with black.
   672   *      (2) The optional best decoding window width is the width of the window
   673   *          that is used to make a decision about whether a transition occurs.
   674   *          It is approximately the average width in pixels of the narrowest
   675   *          white and black bars (i.e., those corresponding to unit width).
   676   *      (3) The optional return signal %nac is a sequence of 0s, 1s,
   677   *          and perhaps a few 2s, giving the number of crossings in each window.
   678   *          On the occasion where there is a '2', it is interpreted as
   679   *          as ending two runs: the previous one and another one that has length 1.
   680   * </pre>
   681   */
   682  NUMA *
   683  pixExtractBarcodeWidths2(PIX        *pixs,
   684                           l_float32   thresh,
   685                           l_float32  *pwidth,
   686                           NUMA      **pnac,
   687                           l_int32     debugflag)
   688  {
   689  NUMA  *nacp, *nad;
   690
   691      PROCNAME("pixExtractBarcodeWidths2");
   692
   693      if (!pixs || pixGetDepth(pixs) != 8)
   694          return (NUMA *)ERROR_PTR("pixs undefined or not 8 bpp", procName, NULL);
   695
   696          /* Get the best estimate of the crossings, in pixel units */
   697      nacp = pixExtractBarcodeCrossings(pixs, thresh, debugflag);
   698
   699          /* Quantize the crossings to get actual windowed data */
   700      nad = numaQuantizeCrossingsByWindow(nacp, 2.0, pwidth, NULL, pnac, debugflag);
   701
   702      numaDestroy(&nacp);
   703      return nad;
   704  }
