   707  /*!
   708   * \brief   pixExtractBarcodeCrossings()
   709   *
   710   * \param[in]    pixs        input image; 8 bpp
   711   * \param[in]    thresh      estimated pixel threshold for crossing
   712   *                           white <--> black; typ. ~120
   713   * \param[in]    debugflag   use 1 to generate debug output
   714   * \return  numa   of crossings, in pixel units, or NULL on error
   715   */
   716  NUMA *
   717  pixExtractBarcodeCrossings(PIX       *pixs,
   718                             l_float32  thresh,
   719                             l_int32    debugflag)
   720  {
   721  l_int32    w;
   722  l_float32  bestthresh;
   723  GPLOT     *gplot;
   724  NUMA      *nas, *nax, *nay, *nad;
   725
   726      PROCNAME("pixExtractBarcodeCrossings");
   727
   728      if (!pixs || pixGetDepth(pixs) != 8)
   729          return (NUMA *)ERROR_PTR("pixs undefined or not 8 bpp", procName, NULL);
   730
   731          /* Scan pixels horizontally and average results */
   732      nas = pixAverageRasterScans(pixs, 51);
   733
   734          /* Interpolate to get 4x the number of values */
   735      w = pixGetWidth(pixs);
   736      numaInterpolateEqxInterval(0.0, 1.0, nas, L_QUADRATIC_INTERP, 0.0,
   737                                 (l_float32)(w - 1), 4 * w + 1, &nax, &nay);
   738
   739      if (debugflag) {
   740          lept_mkdir("lept/barcode");
   741          gplot = gplotCreate("/tmp/lept/barcode/signal", GPLOT_PNG,
   742                              "Pixel values", "dist in pixels", "value");
   743          gplotAddPlot(gplot, nax, nay, GPLOT_LINES, "plot 1");
   744          gplotMakeOutput(gplot);
   745          gplotDestroy(&gplot);
   746      }
   747
   748          /* Locate the crossings.  Run multiple times with different
   749           * thresholds, and choose a threshold in the center of the
   750           * run of thresholds that all give the maximum number of crossings. */
   751      numaSelectCrossingThreshold(nax, nay, thresh, &bestthresh);
   752
   753          /* Get the crossings with the best threshold. */
   754      nad = numaCrossingsByThreshold(nax, nay, bestthresh);
   755
   756      numaDestroy(&nas);
   757      numaDestroy(&nax);
   758      numaDestroy(&nay);
   759      return nad;
   760  }
