   330  /*!
   331   * \brief   pixReadBarcodeWidths()
   332   *
   333   * \param[in]    pixs        of 8 bpp deskewed and cropped barcode
   334   * \param[in]    method      L_USE_WIDTHS, L_USE_WINDOWS;
   335   * \param[in]    debugflag   use 1 to generate debug output
   336   * \return  na   numa of widths (each in set {1,2,3,4}, or NULL on error
   337   */
   338  NUMA *
   339  pixReadBarcodeWidths(PIX     *pixs,
   340                       l_int32  method,
   341                       l_int32  debugflag)
   342  {
   343  l_float32  winwidth;
   344  NUMA      *na;
   345
   346      PROCNAME("pixReadBarcodeWidths");
   347
   348      if (!pixs)
   349          return (NUMA *)ERROR_PTR("pixs not defined", procName, NULL);
   350      if (pixGetDepth(pixs) != 8)
   351          return (NUMA *)ERROR_PTR("pixs not 8 bpp", procName, NULL);
   352      if (method != L_USE_WIDTHS && method != L_USE_WINDOWS)
   353          return (NUMA *)ERROR_PTR("invalid method", procName, NULL);
   354
   355          /* Extract the widths of the lines in each barcode */
   356      if (method == L_USE_WIDTHS)
   357          na = pixExtractBarcodeWidths1(pixs, 120, 0.25, NULL, NULL,
   358                                        debugflag);
   359      else  /* method == L_USE_WINDOWS */
   360          na = pixExtractBarcodeWidths2(pixs, 120, &winwidth,
   361                                        NULL, debugflag);
   362  #if  DEBUG_WIDTHS
   363          if (method == L_USE_WINDOWS)
   364              lept_stderr("Window width for barcode: %7.3f\n", winwidth);
   365          numaWriteStderr(na);
   366  #endif  /* DEBUG_WIDTHS */
   367
   368      if (!na)
   369          return (NUMA *)ERROR_PTR("barcode widths invalid", procName, NULL);
   370
   371      return na;
   372  }
